import os
MODULES=['pcc_neuro_ext111','pcc_pediatric_neuro_ext100','pcc_pediatric_surg_ext100']
FUNCS={
'pcc_neuro_ext111':[('EpilepsyFocalExt','0.18 + Number(input.frequency||4)*0.04 + Number(input.aed||1)*0.2 + Number(input.outcome||1)*0.2'),('EpilepsyGeneralizedExt','0.18 + Number(input.seizureType||1)*0.2 + Number(input.aed||1)*0.2 + Number(input.outcome||1)*0.2'),('StatusEpilepticusExt','0.18 + Number(input.duration||10)*0.04 + Number(input.sezType||1)*0.2 + Number(input.outcome||1)*0.2'),('RefractoryEpilepsyExt','0.18 + Number(input.drugs||3)*0.1 + Number(input.dbs||1)*0.2 + Number(input.outcome||1)*0.2'),('EpilepsySurgeryExt','0.18 + Number(input.resection||1)*0.2 + Number(input.engel||2)*0.1 + Number(input.outcome||1)*0.2'),('TemporalLobeEpilepsyExt','0.18 + Number(input.mri||1)*0.2 + Number(input.surgery||1)*0.2 + Number(input.outcome||1)*0.2'),('FrontalLobeEpilepsyExt','0.18 + Number(input.eeg||1)*0.2 + Number(input.surgery||1)*0.2 + Number(input.outcome||1)*0.2'),('ParietalEpilepsyExt','0.18 + Number(input.eeg||1)*0.2 + Number(input.surgery||1)*0.2 + Number(input.outcome||1)*0.2'),('OccipitalEpilepsyExt','0.18 + Number(input.eeg||1)*0.2 + Number(input.surgery||1)*0.2 + Number(input.outcome||1)*0.2'),('LennoxGastautExt','0.18 + Number(input.seizures||3)*0.1 + Number(input.aed||1)*0.2 + Number(input.outcome||1)*0.2')],
'pcc_pediatric_neuro_ext100':[('PediatricEpilepsyExt','0.18 + Number(input.age||5)*0.04 + Number(input.seizure||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricFocalExt','0.18 + Number(input.age||5)*0.04 + Number(input.mri||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricGeneralizedExt','0.18 + Number(input.age||5)*0.04 + Number(input.eeg||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricStatusExt','0.18 + Number(input.age||5)*0.04 + Number(input.duration||10)*0.04 + Number(input.outcome||1)*0.2'),('PediatricRefractoryExt','0.18 + Number(input.age||5)*0.04 + Number(input.drugs||3)*0.1 + Number(input.outcome||1)*0.2'),('PediatricEpilepsySxExt','0.18 + Number(input.age||7)*0.04 + Number(input.resection||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricTemporalExt','0.18 + Number(input.age||8)*0.04 + Number(input.mri||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricFrontalExt','0.18 + Number(input.age||7)*0.04 + Number(input.eeg||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricMyoclonicExt','0.18 + Number(input.age||5)*0.04 + Number(input.myoclonic||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricAbsenceExt','0.18 + Number(input.age||6)*0.04 + Number(input.eeg||1)*0.2 + Number(input.outcome||1)*0.2')],
'pcc_pediatric_surg_ext100':[('PediatricEpilepsySxResectExt','0.18 + Number(input.age||7)*0.04 + Number(input.resection||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricFocalSxExt','0.18 + Number(input.age||7)*0.04 + Number(input.surgery||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricGeneralizedSxExt','0.18 + Number(input.age||7)*0.04 + Number(input.vns||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricStatusSxExt','0.18 + Number(input.age||5)*0.04 + Number(input.anesthesia||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricRefractorySxExt','0.18 + Number(input.age||7)*0.04 + Number(input.vns||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricEpilepsyVnsExt','0.18 + Number(input.age||8)*0.04 + Number(input.vns||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricTemporalSxExt','0.18 + Number(input.age||8)*0.04 + Number(input.surgery||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricFrontalSxExt','0.18 + Number(input.age||7)*0.04 + Number(input.surgery||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricMyoclonicSxExt','0.18 + Number(input.age||5)*0.04 + Number(input.vns||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricAbsenceSxExt','0.18 + Number(input.age||6)*0.04 + Number(input.aed||1)*0.2 + Number(input.outcome||1)*0.2')]}
for m in MODULES:
    d=f'./{m}'
    os.makedirs(d, exist_ok=True)
    eng=f'// filepath: pcc/{m}/{m}_engine.js\n// {m} engine (deterministic)\nmodule.exports.version=\'v3.210.0\';\nmodule.exports.module=\'{m}\';\nmodule.exports.functions={{}};\n'
    for fn,body in FUNCS[m]:
        eng+=f'module.exports.functions[\'{fn}\']=function(input){{const score=Math.round(({body})*100)/100;return{{version:\'v3.210.0\',module:\'{m}\',function:\'{fn}\',input,score,ts:new Date().toISOString()}};}};\n'
    eng+=f'\n// TS: v3.210.0\n'
    open(f'{d}/{m}_engine.js','w',encoding='utf-8').write(eng)
    test=f'// filepath: pcc/{m}/{m}_test.js\nconst {{functions:F}}=require(\'./{m}_engine\');let pass=0;for(const fn of Object.keys(F)){{const r=F[fn]({{}});if(typeof r.score===\'number\'&&r.score>=0&&r.score<=1.5)pass++;else console.error(\'FAIL\',fn,r);}}console.log(\'{m} unit:\',pass,\'passed\');if(pass!==10)process.exit(1);\n'
    open(f'{d}/{m}_test.js','w',encoding='utf-8').write(test)
    itest=f'// filepath: pcc/{m}/{m}_integration_test.js\nconst {{functions:F}}=require(\'./{m}_engine\');let pass=0;const samples=[{{value:1}},{{value:2}},{{value:3}},{{value:4}},{{value:5}}];for(const fn of Object.keys(F)){{for(const s of samples){{const r=F[fn](s);if(r&&typeof r.score===\'number\')pass++;}}}}console.log(\'{m} integration:\',pass,\'passed\');if(pass!==50)process.exit(1);\n'
    open(f'{d}/{m}_integration_test.js','w',encoding='utf-8').write(itest)
    routes=f'// filepath: pcc/{m}/{m}_routes.js\nconst express=require(\'express\');const {{functions:F}}=require(\'./{m}_engine\');const {{authenticate}}=require(\'../middleware\');const router=express.Router();\nrouter.get(\'/list\',(_req,res)=>res.json({{module:\'{m}\',version:\'v3.210.0\',functions:Object.keys(F)}}));\nrouter.post(\'/call/:fn\',(req,res)=>{{const fn=req.params.fn;if(!F[fn])return res.status(404).json({{error:\'not found\'}});const r=F[fn](req.body||{{}});res.json(r);}});\nrouter.post(\'/record\',(req,res)=>{{const {{fn,payload,decisionId}}=req.body||{{}};if(!F[fn])return res.status(404).json({{error:\'not found\'}});const r=F[fn](payload||{{}});res.json({{decisionId,...r}});}});\nmodule.exports=router;\n'
    open(f'{d}/{m}_routes.js','w',encoding='utf-8').write(routes)
    sql=f'-- pcc/{m}/{m}_up.sql\nIF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N\'[dbo].[{m}]\') AND type = \'U\')\nBEGIN\nCREATE TABLE [dbo].[{m}] (\n  [id] INT IDENTITY(1,1) PRIMARY KEY,\n  [tenant_id] NVARCHAR(64) NOT NULL,\n  [version] NVARCHAR(16) NOT NULL,\n  [module] NVARCHAR(64) NOT NULL,\n  [function] NVARCHAR(128) NOT NULL,\n  [input] NVARCHAR(MAX) NULL,\n  [score] DECIMAL(6,2) NULL,\n  [ts] DATETIME2 DEFAULT SYSUTCDATETIME()\n);\nEND\n'
    open(f'{d}/{m}_up.sql','w',encoding='utf-8').write(sql)
    print(f'{m}: 5 files written')
print('P3-JD v3.210.0: 15 files written')
